files.content:
:root {
  --bg: #1e1e2f;
  --card: #2a2a40;
  --text: #f0f0f5;
  --accent: #6c5ce7;
  --accent-hover: #8577ff;
  --bar-bg: #3d3d5c;
  --hunger: #e17055;
  --happiness: #fdcb6e;
  --energy: #00b894;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.card {
  background: var(--card);
  border-radius: 24px;
  padding: 32px 24px;
  width: 100%;
  max-width: 420px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 24px;
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.4);
}

h1 {
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: 0.5px;
}

.pet {
  width: 120px;
  height: 120px;
  background: var(--accent);
  border-radius: 16px;
  position: relative;
  image-rendering: pixelated;
  box-shadow: 0 0 0 4px var(--bar-bg), 0 0 0 8px var(--card);
  transition: transform 0.2s;
}

.pet .pixel {
  position: absolute;
  background: var(--text);
}

.pet .eye {
  width: 16px;
  height: 16px;
  border-radius: 4px;
  top: 32px;
}

.pet .eye.left {
  left: 24px;
}

.pet .eye.right {
  right: 24px;
}

.pet .mouth {
  width: 40px;
  height: 12px;
  border-radius: 0 0 8px 8px;
  bottom: 32px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--text);
}

.mood {
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--accent-hover);
  min-height: 1.5em;
}

.stats {
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.stat {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.label {
  font-size: 0.875rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: #a0a0b8;
}

.bar {
  height: 20px;
  background: var(--bar-bg);
  border-radius: 10px;
  overflow: hidden;
}

.fill {
  height: 100%;
  border-radius: 10px;
  transition: width 0.4s ease;
}

.fill.hunger {
  background: var(--hunger);
}

.fill.happiness {
  background: var(--happiness);
}

.fill.energy {
  background: var(--energy);
}

.controls {
  display: flex;
  gap: 12px;
  width: 100%;
  flex-wrap: wrap;
  justify-content: center;
}

button {
  flex: 1 1 100px;
  min-width: 90px;
  padding: 14px 20px;
  font-size: 1rem;
  font-weight: 700;
  font-family: inherit;
  color: var(--text);
  background: var(--accent);
  border: none;
  border-radius: 12px;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
}

button:hover {
  background: var(--accent-hover);
}

button:focus-visible {
  outline: 3px solid var(--text);
  outline-offset: 3px;
}

button:active {
  transform: scale(0.96);
}

@media (max-width: 400px) {
  .card {
    padding: 24px 16px;
  }
  h1 {
    font-size: 1.5rem;
  }
  .pet {
    width: 100px;
    height: 100px;
  }
  .pet .eye {
    width: 14px;
    height: 14px;
    top: 26px;
  }
  .pet .eye.left {
    left: 20px;
  }
  .pet .eye.right {
    right: 20px;
  }
  .pet .mouth {
    width: 32px;
    height: 10px;
    bottom: 26px;
  }
  button {
    padding: 12px 16px;
    font-size: 0.9375rem;
  }
}

const stats = {
  hunger: 80,
  happiness: 80,
  energy: 80
};

const moodEl = document.getElementById('mood');
const hungerBar = document.getElementById('hungerBar');
const happinessBar = document.getElementById('happinessBar');
const energyBar = document.getElementById('energyBar');
const bars = {
  hunger: hungerBar,
  happiness: happinessBar,
  energy: energyBar
};

const buttons = {
  hunger: document.getElementById('feedBtn'),
  happiness: document.getElementById('playBtn'),
  energy: document.getElementById('sleepBtn')
};

const actions = {
  hunger: { stat: 'hunger', delta: 15, mood: 'Yum! Feed me more!' },
  happiness: { stat: 'happiness', delta: 15, mood: 'Yay! That was fun!' },
  energy: { stat: 'energy', delta: 20, mood: 'Zzz... recharged!' }
};

function clamp(value, min = 0, max = 100) {
  return Math.min(max, Math.max(min, value));
}

function getMood() {
  if (stats.hunger < 30) return 'Mood: Starving';
  if (stats.energy < 30) return 'Mood: Sleepy';
  if (stats.happiness < 30) return 'Mood: Sad';
  if (stats.hunger > 70 && stats.happiness > 70 && stats.energy > 70) return 'Mood: Happy';
  return 'Mood: Okay';
}

function updateUI() {
  for (const key in bars) {
    bars[key].style.width = stats[key] + '%';
    bars[key].parentElement.setAttribute('aria-valuenow', stats[key]);
  }
  moodEl.textContent = getMood();
}

function handleAction(actionKey) {
  const action = actions[actionKey];
  stats[action.stat] = clamp(stats[action.stat] + action.delta);
  // Other stats decay slightly
  for (const key in stats) {
    if (key !== action.stat) {
      stats[key] = clamp(stats[key] - 5);
    }
  }
  updateUI();
}

for (const key in buttons) {
  buttons[key].addEventListener('click', () => handleAction(key));
}

updateUI();
